contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address callee, bytes memory data, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "balance");

        uint256 balBefore = address(c).balance;

        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        bool unchanged = (address(c).balance == balBefore);
        bool decreased = (address(c).balance < balBefore);

        assert(reverted ? unchanged : (unchanged || decreased));
    }

    receive() external payable {}
}

